'use client'

import { useCallback, useEffect, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { api } from '@/lib/api'
import { CheckCircle2, Copy, Shield } from 'lucide-react'

type MfaSetup = {
  secret: string
  otpauth_uri: string
  qr_data_uri: string
  digits: number
  period_seconds: number
}

/**
 * One authenticator-enrollment experience, shared by the platform-admin
 * console gate and the Settings card.
 *
 * The QR is generated by the backend from a per-account pending secret. The
 * secret stays pending until the server verifies a current six-digit code;
 * recovery codes appear once, after that verification succeeds.
 */
export function MfaEnrollPanel({
  onComplete,
  onRefresh,
}: {
  onComplete?: (recoveryCodes: string[]) => void
  onRefresh?: () => Promise<void> | void
}) {
  const [setup, setSetup] = useState<MfaSetup | null>(null)
  const [code, setCode] = useState('')
  const [recoveryCodes, setRecoveryCodes] = useState<string[] | null>(null)
  const [acknowledged, setAcknowledged] = useState(false)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)

  const begin = useCallback(async () => {
    setError('')
    setBusy(true)
    try {
      const res = await api.beginMfaSetup()
      setSetup(res)
      setCode('')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not start MFA setup')
    } finally {
      setBusy(false)
    }
  }, [])

  useEffect(() => {
    void begin()
  }, [begin])

  const verify = async () => {
    setError('')
    setBusy(true)
    try {
      const res = await api.verifyMfaSetup(code)
      setRecoveryCodes(res.recovery_codes)
      setSetup(null)
      setCode('')
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Invalid verification code'
      // An expired pending secret cannot be verified. Drop the stale QR so
      // the retry control appears and a fresh enrollment can start.
      if (/expired/i.test(message)) {
        setSetup(null)
      }
      setError(message)
    } finally {
      setBusy(false)
    }
  }

  const copy = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text)
    } catch {
      /* manual copy is always available */
    }
  }

  if (recoveryCodes) {
    return (
      <div className="space-y-3 rounded-lg border border-amber-300 bg-amber-50 p-4">
        <p className="text-sm font-semibold text-amber-900">
          Recovery codes — shown once. Store them offline. Cannot be shown again.
        </p>
        <div className="grid grid-cols-2 gap-2 font-mono text-sm">
          {recoveryCodes.map((c) => (
            <span key={c} className="rounded bg-white px-2 py-1">{c}</span>
          ))}
        </div>
        <Button type="button" variant="outline" onClick={() => copy(recoveryCodes.join('\n'))}>
          <Copy className="h-4 w-4" /> Copy codes
        </Button>
        <label className="flex items-start gap-2 text-sm text-amber-900">
          <input
            type="checkbox"
            checked={acknowledged}
            onChange={(e) => setAcknowledged(e.target.checked)}
            className="mt-1"
          />
          I have stored these recovery codes securely.
        </label>
        {!acknowledged && (
          <p className="text-xs text-amber-800">Acknowledge before leaving this page.</p>
        )}
        {onComplete && (
          <Button
            type="button"
            disabled={!acknowledged}
            onClick={() => onComplete(recoveryCodes)}
          >
            <CheckCircle2 className="h-4 w-4" /> Continue
          </Button>
        )}
      </div>
    )
  }

  return (
    <div className="space-y-4 rounded-lg border p-4">
      <div className="flex items-start gap-2">
        <Shield className="mt-0.5 h-5 w-5 text-muted-foreground" aria-hidden="true" />
        <div>
          <p className="text-sm font-semibold">Set up your authenticator</p>
          <p className="text-xs text-muted-foreground">
            Scan this QR code with any TOTP app (Google Authenticator, Microsoft
            Authenticator, 1Password, Authy). Then enter the current six-digit
            code to finish. This screen cannot be skipped.
          </p>
        </div>
      </div>

      {error && <p role="alert" className="text-sm text-red-600">{error}</p>}

      {!setup && busy && (
        <p className="text-sm text-muted-foreground" role="status">
          Preparing your authenticator secret…
        </p>
      )}

      {setup && (
        <>
          <div className="flex justify-center">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={setup.qr_data_uri}
              alt="Authenticator setup QR code"
              width={180}
              height={180}
              className="rounded bg-white p-2"
            />
          </div>

          <div className="space-y-2 rounded-lg border bg-muted/30 p-3">
            <p className="text-xs font-semibold text-muted-foreground">
              Manual setup key
            </p>
            <div className="flex flex-wrap items-center gap-2">
              <code className="break-all rounded bg-white px-2 py-1 text-sm">
                {setup.secret}
              </code>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={() => copy(setup.secret)}
              >
                <Copy className="h-4 w-4" /> Copy key
              </Button>
            </div>
            <p className="text-xs text-muted-foreground">
              Account: time-based one-time password, {setup.digits} digits,
              renewed every {setup.period_seconds} seconds.
            </p>
          </div>

          <Input
            value={code}
            onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
            placeholder="6-digit code"
            inputMode="numeric"
            autoComplete="one-time-code"
            maxLength={6}
            aria-label="6-digit authenticator code"
          />
          <Button
            type="button"
            onClick={() => void verify()}
            disabled={busy || code.length !== 6}
          >
            Verify and enable
          </Button>
        </>
      )}

      {!setup && !busy && error && (
        <Button type="button" variant="outline" onClick={() => void begin()}>
          Retry setup
        </Button>
      )}

      {error && /already (enabled|active)/i.test(error) && onRefresh && (
        <Button type="button" variant="outline" onClick={() => void onRefresh()}>
          Refresh account status
        </Button>
      )}
    </div>
  )
}
